package cn.lambdalib.util.mc;public class Raytrace{public static net.minecraft.util.MovingObjectPosition perform(net.minecraft.world.World w,net.minecraft.util.Vec3 start,net.minecraft.util.Vec3 end,java.util.function.Predicate<net.minecraft.entity.Entity> filter,IBlockSelector block){w.lastTraceStart=start;w.lastTraceEnd=end;var hit=w.nextHit;w.nextHit=null;return hit!=null&&hit.typeOfHit==net.minecraft.util.MovingObjectPosition.MovingObjectType.ENTITY&&filter!=null&&!filter.test(hit.entityHit)?null:hit;}}
